export function orderChat(n,show,close){const index=[...n.id].reduce((v,c)=>v+c.charCodeAt(0),0)%ORDER_LIVES.length;show(n.name,ORDER_LIVES[index],[['Где здесь можно отдохнуть?',()=>show(n.name,'Костёр у южных ворот. Припасы у Бертольда, лекарства у Одилии. За первые поручения Восс выделяет гостевой дом справа от учебного двора — там можно оставить вещи.',[['Спасибо',close]])],['Что слышно о переправе?',()=>show(n.name,'Люди застряли на восточном берегу. Курт пытается запустить паром. Сам он здесь, в заводях, а его сестру держат в старом аббатстве. Если хочешь помочь — поговори с ним.',[['Понятно',close]])],['До встречи',close]])}
